import{z as B,x as R,o as t,c as A,q as o,j as E,D as e,d as r,s as n,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"iBGP 与路由反射器","description":"","frontmatter":{"title":"iBGP 与路由反射器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ibgp-route-reflector.md","filePath":"cs/ibgp-route-reflector.md","lastUpdated":1791063341000}'),p={name:"cs/ibgp-route-reflector.md"};function d(P,a,c,h,f,m){const s=R("Mermaid");return t(),A("div",null,[a[2]||(a[2]=o('<h1 id="ibgp-与路由反射器" tabindex="-1">iBGP 与路由反射器 <a class="header-anchor" href="#ibgp-与路由反射器" aria-label="Permalink to &quot;iBGP 与路由反射器&quot;">​</a></h1><div class="epigraph"><p>iBGP 学来的路由默认不再转给其它 iBGP 对等，于是要全网状；路由反射器把网状收成星形，用簇 ID 防环。</p><footer>—— 据 RFC 4271 iBGP 再通告规则；RFC 4456 BGP Route Reflection 整理</footer></div><p><a href="/cs/bgp-attributes-decision">上一课</a> 选出最佳路径。AS 内部如何把这条路径告诉所有边界路由器？缺口是 <strong>iBGP 全网状问题</strong>与 <strong>RR</strong>：不是再讲 LOCAL_PREF，而是通告范围。本课不把抖动抑制写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 iBGP 允许再通告，AS_PATH 不变，环难查。规则：iBGP 学到的不转给 iBGP。于是 \\(n\\) 台边界要 \\(n(n-1)/2\\) 会话。RR：客户把路由发给反射器，反射器按规则转给其它客户与非客户，Cluster-List / Originator-ID 防反射环。联盟（RFC 5065）是另一刀，把 AS 切成子 AS。</p><p><span class="marginnote">数字实例：\\(n=10\\) 台边界路由器全网状要 \\(10\\times 9/2=45\\) 条会话，\\(n=100\\) 时要 4950 条；换成一台 RR，只需每台各连 RR 的 100 条。RR 最初解决的就是这场运维爆炸。</span></p><p>不要把 RR 当成 OSPF ABR：IGP 仍要全可达下一跳；RR 只减 BGP 会话。</p><p><span class="marginnote">RFC 4456。下一跳原样保留（除非 next-hop-self）。本课不把 add-path 在 RR 上的部署写完。</span></p><h3 id="rr-不是-abr" tabindex="-1">RR 不是 ABR <a class="header-anchor" href="#rr-不是-abr" aria-label="Permalink to &quot;RR 不是 ABR&quot;">​</a></h3><p>iBGP 再通告规则逼出全网状或反射。RR 减会话，数据面仍跟 IGP。只反射最佳会藏备选出口。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：全网状 vs RR 星形 vs 两台 RR 冗余。对照 L2：生成树也是减环，但是转发树；RR 是控制面会话树，数据面仍按 IGP 走。</p><p><span class="marginnote">直觉类比：RR 像班里的学习委员——作业（路由）按规则交给委员，委员誊抄分发给其他同学，并附上「谁最先写的」（Originator-ID）与「经手过哪些委员」（Cluster-List），防止传抄成环。iBGP 原规则禁止同学间转抄，委员是唯一合法例外。</span></p>',13)),(t(),E(l,null,{default:e(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22iBGP%20%E5%AE%A2%E6%88%B7%22%5D%20--%3E%20RR%5B%22%E8%B7%AF%E7%94%B1%E5%8F%8D%E5%B0%84%E5%99%A8%22%5D%0A%20%20C2%5B%22iBGP%20%E5%AE%A2%E6%88%B7%22%5D%20--%3E%20RR%0A%20%20RR%20--%3E%20C1%0A%20%20RR%20--%3E%20C2%0A%20%20CL%5B%22Cluster-List%22%5D%20--%3E%20LOOP%5B%22%E9%98%B2%E5%8F%8D%E5%B0%84%E7%8E%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"决策在每台路由器独立做：RR 若只反射最佳，客户可能看不见备选，热土豆/冷土豆与出口选择会变形——这是 RR 的正确性边界。与 MAC 洪泛不同：这里不洪泛数据包。骨干 IS-IS 提供下一跳可达，BGP 提供前缀。",-1)),(t(),E(l,null,{default:e(()=>[n(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%90%8C%E4%B8%80%E5%89%8D%E7%BC%80%E6%9C%89%E4%B8%A4%E6%9D%A1%E5%8F%AF%E7%94%A8%E8%B7%AF%E7%94%B1%22%5D%20--%3E%20RR%5B%22RR%20%E5%8F%AA%E5%8F%8D%E5%B0%84%E6%9C%80%E4%BD%B3%E7%9A%84%22%5D%0A%20%20RR%20--%3E%20C1%5B%22%E5%AE%A2%E6%88%B7%E5%8F%AA%E8%A7%81%E4%B8%80%E4%B8%AA%E5%87%BA%E5%8F%A3%22%5D%0A%20%20C1%20--%3E%20D%5B%22%E5%87%BA%E5%8F%A3%E9%80%89%E6%8B%A9%E5%81%8F%E7%A6%BB%E5%85%A8%E5%B1%80%E6%9C%80%E4%BC%98%22%5D%0A%20%20P%20--%3E%20NB%5B%22%E5%85%A8%E7%BD%91%E7%8A%B6%E6%97%B6%E4%B8%A4%E6%9D%A1%E9%83%BD%E4%BC%9A%E9%80%81%E8%BE%BE%22%5D%0A%20%20NB%20--%3E%20C2%5B%22%E5%AE%A2%E6%88%B7%E8%87%AA%E8%A1%8C%E6%AF%94%E8%BE%83%E5%86%8D%E9%80%89%E8%B7%AF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">「下一跳在区内不可达」的坑：eBGP 学来的路由，下一跳是对端 AS 的地址；AS 内其它路由器若在 IGP 里查不到这个地址，路由学到了也装不进转发表。next-hop-self 把下一跳改成 RR/ASBR 自己——它必然 IGP 可达。这步做错的典型症状是「BGP 表有、转发表无」。</span></p><p>next-hop-self 常在 RR 或 ASBR 改写下一跳到自己，避免外部下一跳在区内不可达。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BGP Confederations 的全部属性改写。BGP 收敛与抖动抑制是下一课。后课默认：iBGP 不全网状就要 RR 或联盟。</p><p>单 RR 是控制面单点；成对 RR 要注意簇设计，避免分区时环。</p><p>下一课<a href="/cs/bgp-convergence-dampening">BGP 收敛与抖动抑制</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>iBGP 不把学来的路由再给 iBGP，故需网状或 RR。</li><li>RR 用簇与 Originator 防环，可能藏备选路径。</li><li>数据面仍跟 IGP 下一跳。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4271；RFC 4456。</li></ul>',8))])}const G=B(p,[["render",d]]);export{C as __pageData,G as default};
